struct DocState { std::string text; int caret = 0; };

class Editor {
  DocState state_;
  std::vector<DocState> history_;            // caretaker: bounded undo stack
public:
  void save() { history_.push_back(state_); } // value copy == memento
  void undo() {
    if (history_.empty()) return;
    state_ = std::move(history_.back());
    history_.pop_back();
  }
};

