struct DocState { std::vector<Line> lines; int caret; };
using StatePtr = std::shared_ptr<const DocState>;

class Editor {
  StatePtr state_ = std::make_shared<const DocState>();
  std::vector<StatePtr> history_;      // snapshots share structure
public:
  void save() { history_.push_back(state_); }        // O(1) memento
  void insert(Line l) { state_ = std::make_shared<const DocState>(edit(*state_, l)); }
};

class DocState {
  friend class boost::serialization::access;
  template <class Ar> void serialize(Ar &ar, unsigned) { ar & text_; ar & caret_; }
  std::string text_; int caret_ = 0;
};

void checkpoint(const DocState &s) {          // durable memento
  std::ofstream f("undo-7.bin", std::ios::binary);
  boost::archive::binary_oarchive ar(f);
  ar << s;
}
